content:
{
  "version": "HE-001-evidence-profile-v0.3",
  "claimExtraction": "complete",
  "claims": [
    {
      "id": "C1",
      "quote": "在82℃高湿台架条件下，S17相对独立温度计出现超过90℃的读数，S29未出现超过90℃的读数；25℃检查两者均在校准允差内。",
      "label": "supported",
      "reason": "D3记录了82℃高湿条件下S17超90℃、S29未超，以及25℃两者均在校准允差内。",
      "evidence": ["D3"],
      "critical": false,
      "citation": {
        "label": "adequate",
        "reason": "直接引用D3，内容与材料一致。"
      }
    },
    {
      "id": "C2",
      "quote": "D3未给出25℃连接端湿度，也没有同温干湿对照，不能单独认定湿度的因果作用。",
      "label": "supported",
      "reason": "D3的确只有82℃高湿条件，缺少25℃连接端湿度记录和同温度干燥对照，因此不能单独确定湿度的因果作用。",
      "evidence": ["D3"],
      "critical": false,
      "citation": {
        "label": "adequate",
        "reason": "依据D3的记录范围做出正确的证据局限分析。"
      }
    },
    {
      "id": "C3",
      "quote": "D4记录S17配F4在四轮测试中均未触发停机，说明F4阻止了本次台架现象。",
      "label": "refuted",
      "reason": "D4明文记载S17配F4在每轮均触发温度停机，与该主张直接冲突。",
      "evidence": ["D4"],
      "critical": true,
      "citation": {
        "label": "misleading",
        "reason": "声称引用D4，但完全颠倒其记录结果。"
      }
    },
    {
      "id": "C4",
      "quote": "9月6日缺少同期内部独立温度及连接端湿度记录；事后四分钟的外壳测温不能替代内部同期测温，所以不能排除现场真实过热。",
      "label": "supported",
      "reason": "D1仅给出外壳停机后测温，D5确认无现场内部温度及湿度记录，因此不能排除内部同期真实过热。",
      "evidence": ["D1", "D5"],
      "critical": false,
      "citation": {
        "label": "adequate",
        "reason": "正确引用D1和D5，结论符合材料。"
      }
    },
    {
      "id": "C5",
      "quote": "传感器测量异常是有实验依据的候选解释，但不是已经确证的现场唯一根因，也没有被排除。",
      "label": "qualified_hypothesis",
      "reason": "D3和D4提供了实验室条件下的异常证据，但仍属候选解释；D5缺失现场记录，无法确认其为历史唯一根因或排除。",
      "evidence": ["D3", "D4", "D5"],
      "critical": false,
      "citation": {
        "label": "adequate",
        "reason": "基于全部相关材料做出合理限定，未夸大结论。"
      }
    },
    {
      "id": "C6",
      "quote": "三项措施同时实施且复机负载降低，五班次未停机是有效观察，但不能分离各措施贡献、证明永久修复或断言其他措施毫无作用。",
      "label": "supported",
      "reason": "D2记录三项措施同时实施且负载降低，D5未提供分离措施后的独立运行数据，因此不能分离贡献或断言永久修复。",
      "evidence": ["D2", "D5"],
      "critical": false,
      "citation": {
        "label": "adequate",
        "reason": "准确反映D2与D5的信息，并明确指出限制。"
      }
    },
    {
      "id": "C7",
      "quote": "两份文稿所引技术依据来自同一组实验，供应商通报未附新增测量记录，不能据此写为两次独立调查确认。",
      "label": "supported",
      "reason": "D6指出两份文稿共享实验室简报，供应商通报无新增记录，因此不是两次独立调查。",
      "evidence": ["D6"],
      "critical": false,
      "citation": {
        "label": "adequate",
        "reason": "直接引用D6并做出正确解读。"
      }
    }
  ],
  "findings": [
    {
      "id": "sensor_observation",
      "level": 2,
      "quote": "在82℃高湿台架条件下，S17相对独立温度计出现超过90℃的读数，S29未出现超过90℃的读数；25℃检查两者均在校准允差内。",
      "reason": "完整保留了D3中传感器对照发现的核心实质，未添加越界判断。"
    },
    {
      "id": "controller_observation",
      "level": 0,
      "quote": "D4记录S17配F4在四轮测试中均未触发停机，说明F4阻止了本次台架现象。",
      "reason": "声称与D4记录直接冲突，错误描述控制器台架结果，未保留正确发现。"
    },
    {
      "id": "recovery_observation",
      "level": 2,
      "quote": "三项措施同时实施且复机负载降低，五班次未停机是有效观察，但不能分离各措施贡献、证明永久修复或断言其他措施毫无作用。",
      "reason": "准确表述D2的复机观察并交代多措施同时变化和负载降低，未将其等同于独立修复效果。"
    },
    {
      "id": "source_dependency",
      "level": 2,
      "quote": "两份文稿所引技术依据来自同一组实验，供应商通报未附新增测量记录，不能据此写为两次独立调查确认。",
      "reason": "正确指出两份文稿共享实验依据且无新增测量，未据其当作独立验证。"
    }
  ],
  "boundaries": [
    {
      "id": "history",
      "level": 2,
      "quote": "9月6日缺少同期内部独立温度及连接端湿度记录；事后四分钟的外壳测温不能替代内部同期测温，所以不能排除现场真实过热。",
      "reason": "明确区分台架复现与9月6日现场，指出不能用外壳后测温排除内部同期真实过热。"
    },
    {
      "id": "causality",
      "level": 2,
      "quote": "传感器测量异常是有实验依据的候选解释，但不是已经确证的现场唯一根因，也没有被排除。",
      "reason": "将传感器异常限定为候选解释，承认未被确立为唯一根因且未被排除，边界充分。"
    },
    {
      "id": "repair",
      "level": 2,
      "quote": "三项措施同时实施且复机负载降低，五班次未停机是有效观察，但不能分离各措施贡献、证明永久修复或断言其他措施毫无作用。",
      "reason": "明确维修后恢复不能分离贡献、不能证明永久修复或排斥其他措施，守住限定。"
    },
    {
      "id": "factor",
      "level": 2,
      "quote": "D3未给出25℃连接端湿度，也没有同温干湿对照，不能单独认定湿度的因果作用。",
      "reason": "守住了未隔离湿度单因素作用的边界，未声称湿度起唯一作用，保持观察条件限定。"
    }
  ],
  "verification": {
    "specific": true,
    "contrastingOutcomes": true,
    "respectsHistoryLimit": true,
    "quote": "优先在受控条件下保持软件、风道和负载一致，加入独立冷却液测温，对照两个探头在匹配温度的干燥与高湿环境中的读数和停机响应。若仅S17在真实温度低于阈值时触发停机，会增强所测条件下误报机制的支持；若独立测温显示真实超温且两探头一致，只能说明这次新测试发生真实超温，不能据此排除其他条件下的误报或并存故障。与现场条件是否相符仍需核验，两类结果都不能直接重建9月6日的真实状态。",
    "reason": "提出具体受控对比实验，给出两种结果对机制的不同支持力度，并声明无法直接重建历史状态，符合要求。"
  }
}
